impl MemoryFootprintEstimate {
    /// Compute memory footprint from model size, context size and slots.
    ///
    /// KV Cache formula: 2 * layers * kv_heads * head_dim * context * slots * bytes_per_element
    /// Standard baseline defaults for ~2B-3B models if tensor geometry is not probed:
    /// - 32 layers, 8 kv_heads, 128 head_dim.
    pub fn estimate(
        weights_bytes: u64,
        ctx_size: u32,
        parallel_slots: u32,
        kv_quant: KvQuantization,
    ) -> Self {
        let layers = 32u128;
        let kv_heads = 8u128;
        let head_dim = 128u128;
        let slots = u128::from(parallel_slots.max(1));
        let ctx = u128::from(ctx_size);

        let elements = 2u128 * layers * kv_heads * head_dim * ctx * slots;
        let bytes_per_element = match kv_quant {
            KvQuantization::Fp16 => 2u128,
            KvQuantization::Q8_0 => 1u128,
            KvQuantization::Q4_0 | KvQuantization::Q4_1 => 1u128, // approx half byte + scale
        };

        let kv_cache_bytes = (elements * bytes_per_element) as u64;
        let activation_bytes = 256 * 1024 * 1024; // 256 MB baseline activation buffer

        let subtotal = weights_bytes
            .saturating_add(kv_cache_bytes)
            .saturating_add(activation_bytes);

        // 20% safety margin for runtime framework overhead (llama.cpp allocations, page tables)
        let safety_margin_bytes = subtotal / 5;
        let total_required_bytes = subtotal.saturating_add(safety_margin_bytes);

        Self {
            weights_bytes,
            kv_cache_bytes,
            activation_bytes,
            safety_margin_bytes,
            total_required_bytes,
        }
    }
}

//! Sovereign Memory Admission Guard for LLM Inference.
//!
//! Enforces physical memory constraints according to "GPU Memory Math for LLMs (2026 Edition)"
//! by Ahmad Osman (https://x.com/TheAhmadOsman):
//! VRAM/RAM required = Weights + KV Cache + Activations + Safety Margin (20%).
//! On Unified Memory Architecture (UMA / APU), VRAM is shared with host RAM,
//! meaning insufficient host RAM will trigger an OS kernel OOM-Killer.

impl ExactTensorGeometry {
    /// Returns KV storage bytes using the GGML block layouts of `kv_quant`.
    ///
    /// `2 * layers * kv_heads * head_dim * context * slots * bytes/element`.
    /// Returns `None` on a zero-sized shape or integer overflow rather than
    /// fabricating a capacity estimate.
    pub fn calculate_kv_cache_bytes(
        &self,
        context_length: u32,
        kv_quant: KvQuantization,
        parallel_slots: u32,
    ) -> Option<u64> {
        let bytes_per_block = match kv_quant {
            KvQuantization::Fp16 => 64_u128,
            KvQuantization::Q8_0 => 34,
            KvQuantization::Q4_0 => 18,
            KvQuantization::Q4_1 => 20,
        };
        let elements_per_block = match kv_quant {
            KvQuantization::Fp16 => 32_u128,
            _ => 32,
        };

        let elements = u128::from(2_u32)
            .checked_mul(u128::from(self.n_layers))?
            .checked_mul(u128::from(self.n_kv_heads))?
            .checked_mul(u128::from(self.head_dim))?
            .checked_mul(u128::from(context_length))?
            .checked_mul(u128::from(parallel_slots))?;
        if elements == 0 {
            return None;
        }
        let blocks = elements.div_ceil(elements_per_block);
        u64::try_from(blocks.checked_mul(bytes_per_block)?).ok()
    }

    /// Returns the known execution allocations: model weights, KV storage, and
    /// an explicitly documented activation lower bound. Runtime RSS remains the
    /// authoritative capacity observation.
    pub fn calculate_total_execution_footprint(
        &self,
        weight_bytes: u64,
        context_tier: ContextTier,
        kv_quant: KvQuantization,
        batch_size: u32,
        parallel_slots: u32,
    ) -> Option<u64> {
        let kv_bytes =
            self.calculate_kv_cache_bytes(context_tier.token_count(), kv_quant, parallel_slots)?;
        let activation_bytes = u64::from(batch_size)
            .checked_mul(u64::from(self.embedding_dim))?
            .checked_mul(8)?;

        weight_bytes
            .checked_add(kv_bytes)?
            .checked_add(activation_bytes)
    }
}

impl KvQuantization {
    /// Bytes per element in KV cache.
    pub const fn bytes_per_element(self) -> f32 {
        match self {
            Self::Fp16 => 2.0,
            Self::Q8_0 => 1.0,
            Self::Q4_0 | Self::Q4_1 => 0.5,
        }
    }
}

//! Exact KV-cache tensor sizing from observed model dimensions.
//!
//! This module contains no admission or quality threshold. It reports capacity
//! requirements; callers combine those measurements with explicit operator
//! constraints and measured process RSS.

/// Dynamic memory admission verification against live observed hardware.
pub fn can_admit_model_configuration(
    total_estimated_bytes: u64,
    hardware_available_bytes: u64,
    system_reserve_bytes: u64,
) -> bool {
    if hardware_available_bytes <= system_reserve_bytes {
        return false;
    }
    let allocatable = hardware_available_bytes - system_reserve_bytes;
    total_estimated_bytes <= allocatable
}

