/// Charge et analyse la géométrie des crates depuis `infra/crate-topology.json`.
pub fn load_workspace_geometry<P: AsRef<Path>>(
    repo_root: P,
) -> Result<WorkspaceGeometry, std::io::Error> {
    let path = repo_root.as_ref().join("infra/crate-topology.json");
    let content = std::fs::read_to_string(path)?;
    parse_crate_topology_json(&content)
        .map_err(|e| std::io::Error::new(std::io::ErrorKind::InvalidData, e))
}

impl WorkspaceGeometry {
    pub fn from_records(records: Vec<CrateGeometryRecord>) -> Self {
        let total_crates = records.len();
        let total_loc = records.iter().map(|r| r.loc).sum();
        let mut crates = HashMap::new();

        for r in records {
            crates.insert(r.name.clone(), r);
        }

        Self {
            schema: WORKSPACE_GEOMETRY_SCHEMA_V1.to_string(),
            total_crates,
            total_loc,
            crates,
        }
    }

    /// Liste des crates appartenant à une couche donnée ("L0", "L1", etc.).
    pub fn crates_in_layer(&self, layer: &str) -> Vec<&CrateGeometryRecord> {
        let mut list: Vec<&CrateGeometryRecord> =
            self.crates.values().filter(|c| c.layer == layer).collect();
        list.sort_by(|a, b| b.loc.cmp(&a.loc));
        list
    }
}

/// Parseur pur sans I/O du JSON de topologie des crates.
pub fn parse_crate_topology_json(json_str: &str) -> Result<WorkspaceGeometry, serde_json::Error> {
    let raw: RawCrateTopology = serde_json::from_str(json_str)?;
    let records = raw
        .crates
        .into_iter()
        .map(|(name, entry)| CrateGeometryRecord {
            name,
            layer: entry.layer,
            kind: entry.kind,
            loc: entry.loc,
            depends_on: entry.depends_on,
            consumers: entry.consumers,
            justified: entry.justified,
        })
        .collect();

    Ok(WorkspaceGeometry::from_records(records))
}

