//! Emergence runtime — gossip-based coordination without a kernel.
//!
//! Each node runs this loop when the kernel is dead. It floods its local state
//! to the mesh, receives peers' states, and runs a deterministic election to
//! decide who assumes which role. Because the election is pure and the state
//! is shared, every node converges to the same answer.

//! Concrete `PeerResolver` implementation — mesh-aware, health-filtered.
//!
//! This is the bottom-up foundation: without a concrete resolver, every layer
//! above (autonomy loop, CLI, MCP, takeover decision) cannot be tested.

impl MeshTopology {
    pub fn new(network_cidr: String) -> Self {
        Self {
            network_cidr,
            peers: Vec::new(),
        }
    }

    pub fn add_peer(&mut self, peer: PeerIdentity) {
        self.peers.push(peer);
    }
}

//! Emergence — coordination without a central coordinator.
//!
//! Each node runs an autonomy loop (see `local_autonomy`). When the kernel is
//! dead, nodes must still coordinate: who builds? who stores? who is the forge?
//! This layer answers that question without a central scheduler.
//!
//! The mechanism is simple: each node floods its local state to the mesh, and
//! each node independently runs the same deterministic election rule over the
//! shared state. Because the rule is pure and the state is shared, every node
//! converges to the same answer — no consensus protocol, no leader election,
//! just deterministic emergence from local observations.

/// Port: Primary Interface for fetching the canonical Mesh truth from the SSoT.
/// Provider coordination adapters such as Headscale must not redefine this truth.
pub trait MeshStateProvider {
    /// Fetch all known peers from the central nervous system.
    async fn fetch_known_peers(&self) -> Result<Vec<PeerIdentity>, Box<dyn Error>>;
}

impl MeshPeerResolver {
    /// Shared peer resolution used by both `resolve_peers` (role-filtered) and
    /// `resolve_all_peers` (unfiltered). Probes TCP reachability and observes
    /// local OS health, then builds a `PeerEndpoint` per declared node.
    fn resolve_peers_filtered(&self, role_filter: Option<&str>) -> Vec<PeerEndpoint> {
        let declared = match self.read_declared_peers() {
            Ok(d) => d,
            Err(_) => return vec![],
        };

        let mut peers = vec![];
        for node in declared {
            if let Some(role) = role_filter {
                if !node.role.contains(role) {
                    continue;
                }
            }
            let ip = node
                .synapse_ip
                .unwrap_or_else(|| node.management_ip.clone());
            let mut any_reachable = false;

            for port in &node.probe_ports {
                let (reachable, _) = self.probe_port(&ip, *port);
                if reachable {
                    any_reachable = true;
                }
            }

            // OS health: local observation only (remote observation requires SSH/agent).
            let available_mem_mib = crate::os_health::probes::read_available_mem_mib();
            let os_health = if node.id == self.local_node_id {
                let anomalies = self.observe_local_os_health();
                NodeHealthView::from_anomalies(&anomalies, available_mem_mib)
            } else {
                NodeHealthView::default()
            };

            peers.push(PeerEndpoint {
                node_id: node.id,
                role: node.role,
                transport: PeerTransport::Http,
                addr: format!("http://{ip}"),
                probe_ports: node.probe_ports,
                reachable: any_reachable,
                health: os_health,
            });
        }

        peers
    }
}

/// One node's view of the mesh (what it observes about others).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct PeerState {
    pub node_id: String,
    pub role: String,
    pub mode: AutonomyMode,
    pub health_score: u8, // 0-100, higher = healthier
    pub last_seen_unix_s: u64,
    pub capabilities: Vec<String>,
}

/// Mesh peer observer — uses PeerResolver to count reachable peers.
pub struct MeshPeerObserver {
    registry_path: String,
    local_node_id: String,
}

