pub fn advance_storage_operation(
    operation: &StorageOperation,
    event: StorageOperationEvent,
    evidence_refs: &[String],
    now_ms: u64,
) -> StorageOperation {
    let mut next = operation.clone();
    next.evidence_refs.extend(evidence_refs.iter().cloned());
    next.evidence_refs.sort();
    next.evidence_refs.dedup();
    match (operation.phase, event) {
        (StorageOperationPhase::Pending, StorageOperationEvent::StartApply) => {
            next.phase = StorageOperationPhase::Applying
        }
        (StorageOperationPhase::Applying, StorageOperationEvent::ApplyAccepted) => {
            next.phase = StorageOperationPhase::Verifying
        }
        (StorageOperationPhase::Verifying, StorageOperationEvent::ReadBack)
            if next.blockers.is_empty() && !evidence_refs.is_empty() =>
        {
            next.phase = StorageOperationPhase::Succeeded;
            next.completed_at_ms = Some(now_ms);
        }
        (StorageOperationPhase::Verifying, StorageOperationEvent::ReadBack) => next
            .blockers
            .push("storage_operation_read_back_incomplete".to_string()),
        (
            StorageOperationPhase::Pending
            | StorageOperationPhase::Applying
            | StorageOperationPhase::Verifying,
            StorageOperationEvent::Fail,
        ) => {
            next.phase = StorageOperationPhase::Failed;
            next.completed_at_ms = Some(now_ms);
        }
        (
            StorageOperationPhase::Pending
            | StorageOperationPhase::Applying
            | StorageOperationPhase::Verifying,
            StorageOperationEvent::Cancel,
        ) => {
            next.phase = StorageOperationPhase::Cancelled;
            next.completed_at_ms = Some(now_ms);
        }
        _ => next
            .blockers
            .push("storage_operation_transition_invalid".to_string()),
    }
    next
}

pub fn reconcile_storage(
    desired: &StorageDesiredState,
    observed: &StorageObservation,
    budget: &RestartBudget,
    now_unix_ms: u64,
) -> StorageDecision {
    if desired.service != "surrealdb.service" {
        return StorageDecision::Blocked {
            reason: "service_outside_storage_lifecycle_authority".to_string(),
        };
    }
    if desired.health_url != "http://127.0.0.1:8000/health" {
        return StorageDecision::Blocked {
            reason: "health_url_outside_node_local_storage_boundary".to_string(),
        };
    }
    if !desired.desired_running {
        return StorageDecision::ObserveOnly {
            reason: "desired_state_does_not_request_running".to_string(),
        };
    }
    if observed.service_active && observed.health_ok {
        return StorageDecision::Healthy;
    }
    if observed.observation_error.is_some() && observed.service_state == "unknown" {
        return StorageDecision::Blocked {
            reason: "service_observation_unknown".to_string(),
        };
    }

    let window_ms = desired.restart_window_seconds.saturating_mul(1_000);
    let inside_window = now_unix_ms.saturating_sub(budget.window_started_unix_ms) < window_ms;
    if inside_window && budget.restart_count >= desired.max_restarts_per_window {
        return StorageDecision::Blocked {
            reason: "restart_budget_exhausted".to_string(),
        };
    }

    StorageDecision::Restart {
        service: desired.service.clone(),
        stop_condition: "one_restart_then_health_read_back".to_string(),
    }
}

