//! Sovereign Memory Admission Guard for LLM Inference.
//!
//! Enforces physical memory constraints according to "GPU Memory Math for LLMs (2026 Edition)"
//! by Ahmad Osman (https://x.com/TheAhmadOsman):
//! VRAM/RAM required = Weights + KV Cache + Activations + Safety Margin (20%).
//! On Unified Memory Architecture (UMA / APU), VRAM is shared with host RAM,
//! meaning insufficient host RAM will trigger an OS kernel OOM-Killer.

impl LocalRuntimeService<FsLocalModelInventory, SystemdUserLocalRuntime> {
    /// systemd --user template units (`llama-server@`).
    pub fn from_systemd() -> Self {
        let inventory = FsLocalModelInventory::from_env();
        let runtime = SystemdUserLocalRuntime::with_inventory(FsLocalModelInventory::from_env());
        Self { inventory, runtime }
    }
}

//! Local memory observation adapter.
//!
//! Reads the kernel's `/proc` substrate directly (no external host dependency)
//! and assembles the 4-layer `MemoryReport` via the pure parsers in
//! `domain::memory::probe`. This is the localhost-observation surface for the
//! host/node layer; fleet-wide observation is done through `FleetMemoryObserver`
//! which drives either this adapter (local) or `RemoteMemoryAdapter` (SSH).

//! Resource budget and limit types for CYNIC workload admission.
//!
//! WHY THIS EXISTS.
//!
//! CYNIC spawns processes (agents, builds, inference) without any notion of
//! resource consumption. The host crashes when a process saturates CPU, memory,
//! or I/O. This module provides the types needed for admission control and
//! resource isolation.
//!
//! DESIGN PRINCIPLES.
//!
//! 1. **Pure types, no I/O.** This module is in `cynic-protocol` (L0), so it
//!    must remain pure. No `std::process`, no `reqwest`, no `tokio::spawn`.
//! 2. **Optional fields.** `None` means "no limit declared", not "unlimited".
//!    The caller decides how to interpret absence.
//! 3. **Fits-within semantics.** A budget fits within a limit if every declared
//!    field is <= the corresponding limit field. Undeclared fields are not
//!    checked.
//!
//! LAYERS.
//!
//! - `cynic-protocol`: types only (this module)
//! - `cynic-workload`: admission check (does budget fit within available?)
//! - `cynic-host`: isolation (cgroups v2, RLIMIT, taskset)
//! - `cynic-node`: observation (read /proc, cgroups)

impl SystemProbePlatformPort for LinuxPlatformProbe {
    fn observe_platform(&self) -> PlatformObservation {
        #[cfg(target_os = "linux")]
        {
            use cynic_host::process_observation::capture_command;

            let mut zfs_health = serde_json::Value::Null;
            let mut proxmox_resources = serde_json::Value::Null;
            let mut critical_vmids_to_restart = Vec::new();

            if let Ok(output) = capture_command("zpool", &["list", "-H", "-o", "name,health"])
                && output.success
            {
                zfs_health = parse_zpool_health(output.stdout.as_bytes());
            }

            if let Ok(output) = capture_command(
                "sudo",
                &[
                    "-n",
                    "pvesh",
