//! Node identity commands — observe or create the node-local Ed25519 identity.
//!
//! Merged from `node_surface/cli.rs` (16 variants) into the unified node surface.

impl NodeId {
    pub fn from_ed25519(pubkey: &ed25519_dalek::VerifyingKey) -> Self {
        let hash = blake3::hash(pubkey.as_bytes());
        let mut bytes = [0u8; 16];
        bytes.copy_from_slice(&hash.as_bytes()[..16]);
        Self(bytes)
    }

    pub fn from_bytes(bytes: [u8; 16]) -> Self {
        Self(bytes)
    }

    pub fn as_bytes(&self) -> &[u8; 16] {
        &self.0
    }

    pub fn to_hex(&self) -> String {
        hex::encode(self.0)
    }

    pub fn from_hex(hex_str: &str) -> Result<Self, super::error::IdentityError> {
        let bytes = hex::decode(hex_str)
            .map_err(|e| super::error::IdentityError::HexDecode(e.to_string()))?;
        if bytes.len() != 16 {
            return Err(super::error::IdentityError::InvalidLength(bytes.len()));
        }
        let mut arr = [0u8; 16];
        arr.copy_from_slice(&bytes);
        Ok(Self(arr))
    }
}

impl NodeIdentity {
    /// Generate a new random identity using OS entropy.
    /// Requires the `std` feature (not available in Solana/WASM/sandbox targets).
    #[cfg(feature = "std")]
    pub fn generate() -> Self {
        let signing_key =
            ed25519_dalek::SigningKey::generate(&mut rand_core::OsRng);
        let node_id = NodeId::from_ed25519(&signing_key.verifying_key());
        Self { signing_key, node_id }
    }

    /// Construct from an existing signing key — available in all targets.
    pub fn from_signing_key(signing_key: ed25519_dalek::SigningKey) -> Self {
        let node_id = NodeId::from_ed25519(&signing_key.verifying_key());
        Self { signing_key, node_id }
    }

    pub fn sign(&self, message: &[u8]) -> ed25519_dalek::Signature {
        self.signing_key.sign(message)
    }

    pub fn verifying_key(&self) -> ed25519_dalek::VerifyingKey {
        self.signing_key.verifying_key()
    }
}

/// NodeIdentity — full cryptographic identity of a CYNIC node.
///
/// Storage and signing are available in `no_std`.
/// Key generation (`generate()`) requires the `std` feature (OS entropy via OsRng).
/// Same split as `solana-program`: Pubkey (no_std) vs Keypair::generate (std).
#[derive(Debug, Clone, Serialize)]
pub struct NodeIdentity {
    #[serde(skip)]
    pub signing_key: ed25519_dalek::SigningKey,
    pub node_id: NodeId,
}

//! Node identity and enrollment workflow for the CYNIC Trust-Chain vertical.
//!
//! Provides the end-to-end cryptographic root-of-trust pipeline:
//! 1. Generate / load local Ed25519 node signing key.
//! 2. Generate self-signed Certificate Signing Request (CSR) proving possession.
//! 3. Verify CSR authenticity.
//! 4. Issue Kernel-signed Node Enrollment Certificate.
//! 5. Verify and install certificate to `/etc/cynic/node-identity.cert`.

//! Node identity — cryptographic fingerprint from ed25519 keypair.
//!
//! The node_id is NOT spoofable via env var. It is derived from a
//! persistent ed25519 keypair stored in the principal's Hermes directory.
//! `CYNIC_NODE_ID` override is reserved for tests/dev and logs a warning.

impl NodeEnrollmentSignerPort for FileEnrollmentSigner {
    fn key_id(&self) -> String {
        format!(
            "sha256:{}",
            hex::encode(Sha256::digest(self.key.verifying_key().as_bytes()))
        )
    }

    fn sign(&self, payload: &[u8]) -> Result<String, String> {
        Ok(hex::encode(self.key.sign(payload).to_bytes()))
    }

    fn verify(&self, payload: &[u8], signature_hex: &str) -> Result<(), String> {
        let bytes =
            hex::decode(signature_hex).map_err(|_| "enrollment signature is not valid hex")?;
        if bytes.len() != 64 {
            return Err("enrollment signature must be 64 bytes".to_string());
        }
        let mut arr = [0u8; 64];
        arr.copy_from_slice(&bytes);
        let signature = ed25519_dalek::Signature::from_bytes(&arr);
        self.key
            .verifying_key()
            .verify_strict(payload, &signature)
            .map_err(|_| "enrollment signature verification failed".to_string())
    }
}

