pub fn validate_agent_review_receipt(receipt: &AgentReviewReceipt) -> Vec<String> {
    let mut blockers = Vec::new();
    if receipt.schema != AGENT_REVIEW_RECEIPT_SCHEMA {
        blockers.push("agent_review_schema_invalid".to_string());
    }
    if receipt.workload_id.trim().is_empty() {
        blockers.push("agent_review_workload_id_missing".to_string());
    }
    if !valid_sha256_digest(&receipt.proposal_digest) {
        blockers.push("agent_review_proposal_digest_invalid".to_string());
    }
    if requires_observed_inputs(receipt.state) && receipt.observed_input_refs.is_empty() {
        blockers.push("agent_review_observed_inputs_missing".to_string());
    }
    if requires_validation_evidence(receipt.state) && receipt.validation_evidence_refs.is_empty() {
        blockers.push("agent_review_validation_evidence_missing".to_string());
    }
    if receipt.state == AgentReviewState::HumanAcknowledged
        && receipt.human_acknowledgement.is_none()
    {
        blockers.push("agent_review_human_acknowledgement_missing".to_string());
    }
    for reference in receipt
        .observed_input_refs
        .iter()
        .chain(receipt.validation_evidence_refs.iter())
        .chain(receipt.human_acknowledgement.iter())
    {
        if !valid_evidence_ref(reference) {
            blockers.push("agent_review_evidence_ref_invalid".to_string());
        }
    }
    blockers.sort();
    blockers.dedup();
    blockers
}

pub fn persist_local_proof(
    mut report: SourceRepositoryBootstrapReport,
    state_root: &Path,
    observed_at_unix_ms: u128,
) -> SourceRepositoryBootstrapReport {
    let provenance = match report
        .after
        .as_ref()
        .and_then(|observation| observation.observed_revision.as_deref())
    {
        Some(revision) => vec![format!("git:{revision}")],
        None => {
            return mark_unknown(report, "source_bootstrap_proof_revision_missing");
        }
    };
    report = mark_unknown(report, "source_bootstrap_kernel_commit_missing");
    let evidence = match build_evidence_envelope(
        &format!(
            "source-repository:{}:{}",
            report.request.node_id, report.request.repository_id
        ),
        "cynic-node/source-bootstrap",
        observed_at_unix_ms,
        provenance,
        &report,
    ) {
        Ok(evidence) => evidence,
        Err(failure) => {
            return mark_unknown(report, format!("source_bootstrap_evidence_build:{failure}"));
        }
    };
    let store = LocalContentAddressedEvidenceStore::new(state_root.join("evidence"));
    match store.persist(&evidence) {
        Ok(local_ref) => {
            report.proof_ref = Some(evidence.digest.clone());
            report.proof_authority = SourceRepositoryBootstrapProofAuthority::LocalContentAddressed;
            report.evidence_refs.push(evidence.digest);
            report.evidence_refs.push(local_ref);
        }
        Err(failure) => {
            report = mark_unknown(
                report,
                format!("source_bootstrap_evidence_persist:{failure}"),
            );
        }
    }
    report
}

impl LocalContentAddressedEvidenceStore {
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    fn record_path(&self, digest: &str) -> Result<PathBuf, String> {
        let name = digest
            .strip_prefix("sha256:")
            .filter(|value| value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit()))
            .ok_or_else(|| "invalid_evidence_digest".to_string())?;
        Ok(self.root.join(format!("{name}.json")))
    }
}

pub struct RequiredProof {
    pub gate: String,
    pub subject: String,
}

impl IncidentAuthorityPort for LocalIncidentAuthority {
    fn verify_and_consume(
        &self,
        admission: &BreakglassAdmission,
        target_scope: &str,
        action: &str,
        now_unix_s: u64,
    ) -> Result<BreakglassConsumptionProof, CynicErrorCode> {
        if !admission
            .validate_for(target_scope, action, now_unix_s)
            .is_empty()
        {
            return Err(CynicErrorCode::BreakglassAdmissionInvalid);
        }
        let payload = admission
            .signing_payload()
            .map_err(|_| CynicErrorCode::BreakglassSignatureInvalid)?;
        let signature: [u8; 64] = hex::decode(&admission.signature_hex)
            .map_err(|_| CynicErrorCode::BreakglassSignatureInvalid)?
            .try_into()
            .map_err(|_| CynicErrorCode::BreakglassSignatureInvalid)?;
        self.verifying_key(&admission.authority_key_id)?
            .verify(&payload, &Signature::from_bytes(&signature))
            .map_err(|_| CynicErrorCode::BreakglassSignatureInvalid)?;
        let proof = BreakglassConsumptionProof {
            schema: CONSUMPTION_SCHEMA.to_string(),
            receipt_id: admission.receipt_id.clone(),
            target_scope: target_scope.to_string(),
            action: action.to_string(),
            consumed_at_unix_s: now_unix_s,
            authority_key_id: admission.authority_key_id.clone(),
            admission_digest: format!("sha256:{}", hex::encode(Sha256::digest(payload))),
        };
        self.persist_and_read_back(&proof)?;
        Ok(proof)
    }
}

