pub fn compress_build_proof(
    epoch: u64,
    commit_hash: &str,
    crates_affected: Vec<String>,
    lines_inserted: usize,
    lines_deleted: usize,
    audit_v2_status: &str,
    q_score_bps: Option<u32>,
    raw_summary: &str,
) -> BuildProofCard {
    let timestamp = Utc::now().to_rfc3339();
    let sanitized_summary = sanitize_public_text(raw_summary);

    let mut hasher = Sha256::new();
    hasher.update(epoch.to_be_bytes());
    hasher.update(commit_hash.as_bytes());
    hasher.update(timestamp.as_bytes());
    hasher.update(lines_inserted.to_be_bytes());
    hasher.update(lines_deleted.to_be_bytes());
    hasher.update(audit_v2_status.as_bytes());
    for c in &crates_affected {
        hasher.update(c.as_bytes());
    }
    let proof_digest = hex::encode(hasher.finalize());

    let card_id = format!(
        "bpc-{}-{}",
        &commit_hash[..commit_hash.len().min(8)],
        &proof_digest[..8]
    );

    BuildProofCard {
        schema: BUILD_PROOF_CARD_SCHEMA_V1.to_string(),
        card_id,
        epoch,
        timestamp,
        commit_hash: commit_hash.to_string(),
        crates_affected,
        lines_inserted,
        lines_deleted,
        audit_v2_status: audit_v2_status.to_string(),
        q_score_bps,
        proof_digest,
        public_summary: sanitized_summary,
    }
}

impl BuildProofObservation {
    /// Whether this observation permits promoting the commit.
    ///
    /// Only a converged proof does. Everything else is absence of evidence, and
    /// absence is not consent.
    pub fn permits_promotion(&self) -> bool {
        matches!(self, Self::Converged { .. })
    }

    /// Human-readable detail for the gate record.
    pub fn detail(&self) -> String {
        match self {
            Self::Converged { node } => {
                format!("builder proof converged on {node}")
            }
            Self::Blocked { node, reason } => {
                format!("builder proof blocked on {node}: {reason}")
            }
            Self::NeverTested => {
                "no builder proof exists for this commit: it was never validated".to_string()
            }
            Self::Unreadable { skipped_lines } => format!(
                "builder proof log is unreadable: {skipped_lines} line(s) are not valid JSON"
            ),
            Self::UnknownStatus { node, status } => format!(
                "builder proof on {node} carries status '{status}', which this build does not recognise: not a pass"
            ),
        }
    }

    /// Project onto the release gate record shape.
    pub fn to_gate_record(&self, observed_at_unix_s: u64) -> GateProofRecord {
        GateProofRecord {
            name: BUILD_PROOF_GATE_NAME.to_string(),
            passed: self.permits_promotion(),
            detail: self.detail(),
            observed_at_unix_s,
        }
    }
}

impl BuildConformanceEvidence {
    pub fn from_build_proof(proof: &BuildProof) -> Self {
        Self {
            schema: "cynic.host.build_conformance_evidence.v1",
            status: match proof.status {
                "proved" => "proved",
                "failed" => "failed",
                _ => "unknown",
            },
            source_commit: proof.source_commit.clone(),
            evidence_refs: proof.evidence_refs.clone(),
            blockers: proof.blockers.clone(),
        }
    }

    pub fn from_content_addressed_envelope(
        requested_digest: &str,
        envelope: &EvidenceEnvelope,
    ) -> Result<Self, String> {
        if envelope.digest != requested_digest {
            return Err("build_evidence_digest_mismatch".to_string());
        }
        if !envelope.subject.starts_with("build-workload:")
            || !envelope.producer.starts_with("cynic-node/build-scheduler:")
        {
            return Err("build_evidence_provenance_rejected".to_string());
        }
        let read_back: CanonicalGateReadBack = serde_json::from_value(envelope.payload.clone())
            .map_err(|_| "build_evidence_payload_invalid".to_string())?;
        if read_back.schema != CANONICAL_GATE_READ_BACK_SCHEMA
            || read_back.source_commit.trim().is_empty()
            || read_back.argv.is_empty()
            || read_back
                .argv
                .iter()
                .any(|argument| argument.trim().is_empty())
        {
            return Err("build_evidence_contract_rejected".to_string());
        }
        let (status, blockers) = if read_back.exit_code == Some(0) {
            ("proved", Vec::new())
        } else {
            (
                "failed",
                vec![format!(
                    "canonical_gate_exit_code:{:?}",
                    read_back.exit_code
                )],
            )
        };
        Ok(Self {
            schema: "cynic.host.build_conformance_evidence.v1",
            status,
            source_commit: read_back.source_commit,
            evidence_refs: vec![requested_digest.to_string()],
            blockers,
        })
    }
}

