    pub fn new(
        source_commit: impl Into<String>,
        package: Option<String>,
        phase: BuildProofPhase,
    ) -> Self {
        Self {
            schema: BUILD_PROOF_REQUEST_SCHEMA.to_string(),
            source_commit: source_commit.into(),
            package,
            phase,
            network_mode: BuildProofNetworkMode::Offline,
