//! Multi-objective inference selection through Pareto dominance.
//!
//! The frontier contains every configuration that is not strictly worse than
//! another observed configuration. No absent metric is imputed. A single
//! "balanced" choice uses a documented, equal-regret projection only after the
//! frontier is known.

impl EmpiricalCdf {
    /// Constructs an ECDF from a collection of observed raw scores.
    pub fn from_samples(mut samples: Vec<f64>) -> Self {
        samples.sort_by(|a, b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
        Self {
            sorted_samples: samples,
        }
    }

    /// Evaluates the percentile rank of `val` in $[0.0, 1.0]$.
    pub fn percentile(&self, val: f64) -> f64 {
        if self.sorted_samples.is_empty() {
            return 0.0;
        }
        let count_below = self
            .sorted_samples
            .iter()
            .take_while(|&&sample| sample <= val)
            .count();
        count_below as f64 / self.sorted_samples.len() as f64
    }
}

/// Compute certainty from Welford stats + observation count.
/// Pure domain logic — used by storage adapters and tests.
///
/// Formula: `concordance * volume` where:
/// - `concordance = 1 / (1 + (stddev / phi-cubed-inverse)^2)` — quadratic decay, phi-calibrated
/// - `volume` is dynamic:
///   - High consensus (concordance > phi-inverse) allows fast-track crystallization.
///   - Baseline ramp to 21 observations.
///
/// Crystallization (certainty >= phi-inverse) can now occur at ~13 observations if
/// consensus is perfect, or 21 if consensus is marginal.
/// Compute certainty from Welford stats + observation count.
/// Formula: `concordance * volume`
/// Volume is modulated by consensus, diversity, and source reliability.
pub fn compute_certainty(
    variance_m2: f64,
    observations: u32,
    source_diversity: u32,
    reliability_weight: f64,
) -> f64 {
    let stddev = if observations > 1 {
        (variance_m2 / (observations as f64 - 1.0)).sqrt()
    } else {
        0.0
    };
    let ratio = stddev / PHI_INV3;
    let concordance = 1.0 / (1.0 + ratio * ratio);

    let consensus_bonus = 1.0 + (0.618 * concordance);
    let diversity_bonus = 1.0 + (0.618 * (source_diversity as f64 - 1.0).max(0.0) / 5.0).min(0.618);

    let effective_obs =
        observations as f64 * reliability_weight * consensus_bonus * diversity_bonus;

    let volume = (effective_obs / MIN_CRYSTALLIZATION_CYCLES as f64).min(1.0);
    concordance * volume
}

pub fn kl_divergence_bits(p: &[f64], q: &[f64]) -> Result<f64, EntropyError> {
    if p.len() != q.len() {
        return Err(EntropyError::LengthMismatch { lhs: p.len(), rhs: q.len() });
    }
    validate_distribution(p)?;
    validate_distribution(q)?;
    let mut divergence = 0.0_f64;
    for (index, (pi, qi)) in p.iter().zip(q.iter()).enumerate() {
        if *pi > 0.0 {
            if *qi <= 0.0 {
                return Err(EntropyError::KlDivergenceDivergent { index });
            }
            divergence += pi * (pi / qi).ln() / LN_2;
        }
    }
    if divergence < 0.0 && divergence > -1e-12 {
        divergence = 0.0;
    }
    Ok(divergence)
}

