/// Pure decision: may this citizen mutate `target_scope`?
///
/// This is the single canonical admission rule. Surfaces project it; they must
/// not re-derive it locally (invariant #6).
///
/// `held_claim` is the scope the agent actually holds, if any. `None` means no
/// claim — and no claim means no mutation, which is the whole point of the
/// coordination contract. A store that cannot be read is *not* an implicit
/// grant: the caller passes `store_available = false` and the mutation is
/// refused with `AgentCoordinationStoreUnavailable`, never silently allowed.
pub fn admit_citizenship_mutation(
    record: &AgentCitizenshipRecord,
    held_claim: Option<&AgentScope>,
    requested: &AgentBudgets,
    target_scope: &AgentScope,
    store_available: bool,
) -> MutationAdmission {
    let mut codes = Vec::new();

    if !store_available {
        codes.push(CynicErrorCode::AgentCoordinationStoreUnavailable);
    }

    match held_claim {
        None => codes.push(CynicErrorCode::AgentMutationWithoutClaim),
        Some(held) => {
            if !held.contains(target_scope) {
                codes.push(CynicErrorCode::AgentScopeConflict);
            }
        }
    }

    if !budgets_within(&record.budgets, requested) {
        codes.push(CynicErrorCode::AgentBudgetExceeded);
    }

    if codes.is_empty() {
        MutationAdmission::Admitted
    } else {
        MutationAdmission::Refused { codes }
    }
}

impl Claim {
    /// Remaining budget = granted budget − consumed budget (saturating).
    pub fn remaining_budget(&self) -> AgentBudgets {
        AgentBudgets {
            actions: self
                .request
                .budget
                .actions
                .saturating_sub(self.consumed.actions),
            wall_seconds: self
                .request
                .budget
                .wall_seconds
                .saturating_sub(self.consumed.wall_seconds),
        }
    }

    /// Pure consumption step: returns a new claim with the delta added to
    /// `consumed`, saturating at the granted budget. Refuses nothing here —
    /// admission is decided by [`admit_mutation`]; this only records.
    pub fn record_consumption(&self, delta: &AgentBudgets) -> Claim {
        let mut next = self.clone();
        next.consumed.actions = next.consumed.actions.saturating_add(delta.actions);
        next.consumed.wall_seconds = next
            .consumed
            .wall_seconds
            .saturating_add(delta.wall_seconds);
        if next.consumed.actions > next.request.budget.actions {
            next.consumed.actions = next.request.budget.actions;
        }
        if next.consumed.wall_seconds > next.request.budget.wall_seconds {
            next.consumed.wall_seconds = next.request.budget.wall_seconds;
        }
        next
    }

    pub fn is_active(&self) -> bool {
        matches!(self.status, ClaimStatus::Active)
    }

    pub fn is_expired_at(&self, now_unix_ms: u64) -> bool {
        now_unix_ms >= self.expires_at_unix_ms
    }

    pub fn is_heartbeat_stale(&self, now_unix_ms: u64) -> bool {
        let ttl_ms = self
            .expires_at_unix_ms
            .saturating_sub(self.granted_at_unix_ms);
        let stale_threshold = self.granted_at_unix_ms.saturating_add(ttl_ms * 8 / 10);
        now_unix_ms >= stale_threshold
    }
}

