pub fn run_gates(state_path: &Path, execute: bool, runner: &dyn ArgvRunner) -> LifecycleGateReport {
    let mut state = load_state(state_path);
    let policy = phase_policy(&state.current_phase);
    let mut results = Vec::new();
    let mut all_required_ok = true;

    for g in &policy.gates {
        if !execute {
            results.push(GateResult {
                id: g.id,
                command: g.command,
                required: g.required,
                ran: false,
                ok: false,
                exit_code: None,
                detail: "planned only — pass --yes to execute gates".into(),
            });
            if g.required {
                all_required_ok = false;
            }
            continue;
        }

        let argv = split_command(g.command);
        let out = runner.run(&argv);
        if let Some(err) = &out.spawn_error {
            if g.required {
                all_required_ok = false;
            }
            results.push(GateResult {
                id: g.id,
                command: g.command,
                required: g.required,
                ran: true,
                ok: false,
                exit_code: None,
                detail: err.clone(),
            });
            continue;
        }

        let mut ok = out.success();
        if let Some(st) = json_status(&out.stdout) {
            // Soft-fail statuses must not promote authority (sovereignty bar):
            // insufficient_evidence / below_target are honest residuals, not green.
            ok = ok
                && st != "blocked"
                && st != "error"
                && st != "degraded"
                && st != "insufficient_evidence"

