//! Ledger engine — append-only, monotone, idempotent, double-entry.
//!
//! This module provides the core ledger logic. It is pure — no I/O.

/// What the ledger comparison found.
#[derive(Debug, Clone)]
pub struct LedgerVerdict {
    /// Violations matched to a ledger entry at or below its recorded count.
    pub accounted: usize,
    /// Identities observed but absent from the ledger, or above their count.
    /// Each is a new or regressed violation: the gate must fail.
    pub unaccounted: Vec<String>,
    /// Ledger entries with no observed violation. Debt paid but not recorded as
    /// paid: the gate must fail, because a stale ledger hides that it is stale.
    pub stale: Vec<String>,
}

/// A resource ledger — append-only, monotone, idempotent, double-entry.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ResourceLedger {
    pub ledger_id: String,
    pub resource_type: ResourceType,
    /// Append-only entries. Never modified or deleted.
    pub entries: Vec<ResourceTransaction>,
    /// Derived balance — computed from entries, never stored independently.
    pub balance: ResourceUnit,
}

/// The ledger engine — manages resource ledgers with strict invariants.
#[derive(Debug, Clone)]
pub struct LedgerEngine {
    ledgers: Vec<ResourceLedger>,
}

/// Energy ledger — tracks allocations and consumption.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct EnergyLedger {
    pub schema: String,
    pub allocations: Vec<EnergyAllocation>,
    pub consumptions: Vec<EnergyConsumption>,
    pub proofs: Vec<EnergyProof>,
}

/// Channel settlement ledger — records channel settlements as ResourceTransaction.
///
/// Each settlement produces two transactions:
/// - Debit from initiator (budget consumed)
/// - Credit to worker (budget earned)
///
/// This bridges the off-chain channel state with the on-chain ledger.
pub struct ChannelSettlementLedger {
    ledger: ResourceLedger,
}

//! Energy ledger — allocate, track, and prove energy consumption for agent actions.
//!
//! Every agent action costs energy. The ledger ensures:
//! 1. Budget is allocated before execution (no blind spending)
//! 2. Consumption is measured and recorded (no silent overruns)
//! 3. Proof is generated (audit trail)
//!
//! Pattern:
//!   AgentAction → Ledger::allocate(budget) → execute → Ledger::record(consumed) → Proof
//!
//! Reusable by: cleanup, merge, disk extension, LLM calls, any privileged operation.

impl CausalEvidenceRefs {
    fn all(&self) -> Vec<&EvidenceRef> {
        let mut evidence = vec![&self.desired_state];
        evidence.extend(&self.observations);
        evidence.push(&self.decision);
        evidence.extend(self.authorization.as_ref());
        evidence.extend(self.action_receipt.as_ref());
        evidence.extend(self.read_back.as_ref());
        evidence
    }

    fn digests(&self) -> Vec<String> {
        let mut digests = self
            .all()
            .into_iter()
            .map(|evidence| evidence.digest.clone())
            .collect::<Vec<_>>();
        digests.sort();
        digests.dedup();
        digests
    }
}

