pub fn command_to_argv(command: &HostCommandSurface) -> Result<Vec<String>, String> {
    invocation_to_argv(&command.invocation)
}

pub struct HostCommandContext {
    pub principal: PrincipalCommandContext,
    pub privilege: PrivilegeCommandContext,
    pub packages: PackageCommandContext,
    pub services: ServiceCommandContext,
}

pub struct HostExecRequest {
    pub action: String, // ex: "systemd_restart", "shell"
    pub command: Vec<String>,
}

pub fn invocation_to_argv(invocation: &HostCommandInvocation) -> Result<Vec<String>, String> {
    match invocation {
        HostCommandInvocation::Argv { argv } => Ok(argv.clone()),
        HostCommandInvocation::InstallDir { path, policy } => Ok(vec![
            "install".to_string(),
            "-d".to_string(),
            "-o".to_string(),
            policy.owner.user.to_string(),
            "-g".to_string(),
            policy.owner.group.to_string(),
            "-m".to_string(),
            policy.mode.octal.to_string(),
            path.clone(),
        ]),
        HostCommandInvocation::InstallFile {
            source,
            target,
            policy,
        } => Ok(vec![
            "install".to_string(),
            "-o".to_string(),
            policy.owner.user.to_string(),
            "-g".to_string(),
            policy.owner.group.to_string(),
            "-m".to_string(),
            policy.mode.octal.to_string(),
            source.clone(),
            target.clone(),
        ]),
        HostCommandInvocation::ValidateSudoers { path } => Ok(vec![
            current_runtime_layout().visudo_bin(),
            "-cf".to_string(),
            path.clone(),
        ]),
        HostCommandInvocation::Shell { .. }
        | HostCommandInvocation::Expectation { .. }
        | HostCommandInvocation::PackagePresence { .. } => {
            Err("host execution supports only argv/install/visudo surfaces".to_string())
        }
    }
}

pub struct HostArgvCommand {
    pub role: String,
    pub argv: Vec<String>,
}

pub trait HostCommandRunnerPort {
    fn run_operation(&self, operation: &AdmittedHostOperation) -> HostCommandResult;
}

impl HostCommandContext {
    pub fn from_current_runtime() -> Self {
        Self {
            principal: PrincipalCommandContext::from_current_runtime(),
            privilege: PrivilegeCommandContext::from_current_runtime(),
            packages: PackageCommandContext::from_current_runtime(),
            services: ServiceCommandContext::from_current_runtime(),
        }
    }
}

