pub fn looks_like_solana_address(s: &str) -> bool {
    let len = s.len();
    (32..=44).contains(&len)
        && s.chars()
            .all(|c| c.is_ascii_alphanumeric() && c != '0' && c != 'O' && c != 'I' && c != 'l')
}

